// ***************
// Filename: symbol_overlay_regs_if.sv
// Author: FPGA Cores 4 U
// Description: Register interface of symbol_overlay: joins the register map
//   symbol_overlay_regs (modport regs) and the logic symbol_overlay (modport
//   core). cfg_* go from the register map to the logic (register values, _wr
//   write pulses, _rd read pulses), sts_* come back (values read, _set / _clr
//   hardware set / clear pulses). A logic block ties every sts_* member it
//   does not use to 0. Generated by ip/scripts/regmap_gen.py from
//   symbol_overlay_regs.json: edit the JSON and regenerate.
// Date: 2026-10-20
interface symbol_overlay_regs_if #(
  parameter int NOBJ = 4,
  parameter int NTXT = 4
) ();
  logic [4-1:0] cfg_ctrl;
  logic cfg_ctrl_wr;
  logic sts_commit;
  logic cfg_commit;
  logic cfg_commit_wr;
  logic [32-1:0] sts_status;
  logic [20-1:0] sts_frame_num;
  logic [20-1:0] cfg_frame_num;
  logic cfg_frame_num_wr;
  logic [((NOBJ > 16 ? 16 : NOBJ))*(32)-1:0] cfg_obj_ctrl;
  logic [(NOBJ > 16 ? 16 : NOBJ)-1:0] cfg_obj_ctrl_wr;
  logic [((NOBJ > 16 ? 16 : NOBJ))*(32)-1:0] cfg_obj_x;
  logic [(NOBJ > 16 ? 16 : NOBJ)-1:0] cfg_obj_x_wr;
  logic [((NOBJ > 16 ? 16 : NOBJ))*(32)-1:0] cfg_obj_y;
  logic [(NOBJ > 16 ? 16 : NOBJ)-1:0] cfg_obj_y_wr;
  logic [((NOBJ > 16 ? 16 : NOBJ))*(24)-1:0] cfg_obj_color;
  logic [(NOBJ > 16 ? 16 : NOBJ)-1:0] cfg_obj_color_wr;
  logic [((NTXT < 1 ? 1 : NTXT))*(32)-1:0] cfg_txt_ctrl;
  logic [(NTXT < 1 ? 1 : NTXT)-1:0] cfg_txt_ctrl_wr;
  logic [((NTXT < 1 ? 1 : NTXT))*(32)-1:0] cfg_txt_pos;
  logic [(NTXT < 1 ? 1 : NTXT)-1:0] cfg_txt_pos_wr;
  logic [((NTXT < 1 ? 1 : NTXT))*(24)-1:0] cfg_txt_color;
  logic [(NTXT < 1 ? 1 : NTXT)-1:0] cfg_txt_color_wr;
  logic [(4 * (NTXT < 1 ? 1 : NTXT))*(32)-1:0] cfg_txt_chars;
  logic [4 * (NTXT < 1 ? 1 : NTXT)-1:0] cfg_txt_chars_wr;
  logic [((NOBJ > 16 ? 16 : NOBJ))*(32)-1:0] cfg_obj_label;
  logic [(NOBJ > 16 ? 16 : NOBJ)-1:0] cfg_obj_label_wr;
  logic [((NOBJ > 16 ? NOBJ - 16 : 1))*(32)-1:0] cfg_obj2_ctrl;
  logic [(NOBJ > 16 ? NOBJ - 16 : 1)-1:0] cfg_obj2_ctrl_wr;
  logic [((NOBJ > 16 ? NOBJ - 16 : 1))*(32)-1:0] cfg_obj2_x;
  logic [(NOBJ > 16 ? NOBJ - 16 : 1)-1:0] cfg_obj2_x_wr;
  logic [((NOBJ > 16 ? NOBJ - 16 : 1))*(32)-1:0] cfg_obj2_y;
  logic [(NOBJ > 16 ? NOBJ - 16 : 1)-1:0] cfg_obj2_y_wr;
  logic [((NOBJ > 16 ? NOBJ - 16 : 1))*(24)-1:0] cfg_obj2_color;
  logic [(NOBJ > 16 ? NOBJ - 16 : 1)-1:0] cfg_obj2_color_wr;
  logic [((NOBJ > 16 ? NOBJ - 16 : 1))*(32)-1:0] cfg_obj2_label;
  logic [(NOBJ > 16 ? NOBJ - 16 : 1)-1:0] cfg_obj2_label_wr;

  modport regs (output cfg_ctrl, cfg_ctrl_wr, cfg_commit, cfg_commit_wr, cfg_frame_num, cfg_frame_num_wr,
    cfg_obj_ctrl, cfg_obj_ctrl_wr, cfg_obj_x, cfg_obj_x_wr, cfg_obj_y, cfg_obj_y_wr, cfg_obj_color,
    cfg_obj_color_wr, cfg_txt_ctrl, cfg_txt_ctrl_wr, cfg_txt_pos, cfg_txt_pos_wr, cfg_txt_color,
    cfg_txt_color_wr, cfg_txt_chars, cfg_txt_chars_wr, cfg_obj_label, cfg_obj_label_wr, cfg_obj2_ctrl,
    cfg_obj2_ctrl_wr, cfg_obj2_x, cfg_obj2_x_wr, cfg_obj2_y, cfg_obj2_y_wr, cfg_obj2_color, cfg_obj2_color_wr,
    cfg_obj2_label, cfg_obj2_label_wr, input sts_commit, sts_status, sts_frame_num);
  modport core (output sts_commit, sts_status, sts_frame_num, input cfg_ctrl, cfg_ctrl_wr, cfg_commit,
    cfg_commit_wr, cfg_frame_num, cfg_frame_num_wr, cfg_obj_ctrl, cfg_obj_ctrl_wr, cfg_obj_x, cfg_obj_x_wr,
    cfg_obj_y, cfg_obj_y_wr, cfg_obj_color, cfg_obj_color_wr, cfg_txt_ctrl, cfg_txt_ctrl_wr, cfg_txt_pos,
    cfg_txt_pos_wr, cfg_txt_color, cfg_txt_color_wr, cfg_txt_chars, cfg_txt_chars_wr, cfg_obj_label,
    cfg_obj_label_wr, cfg_obj2_ctrl, cfg_obj2_ctrl_wr, cfg_obj2_x, cfg_obj2_x_wr, cfg_obj2_y, cfg_obj2_y_wr,
    cfg_obj2_color, cfg_obj2_color_wr, cfg_obj2_label, cfg_obj2_label_wr);
  modport monitor (input cfg_ctrl, cfg_ctrl_wr, cfg_commit, cfg_commit_wr, cfg_frame_num, cfg_frame_num_wr,
    cfg_obj_ctrl, cfg_obj_ctrl_wr, cfg_obj_x, cfg_obj_x_wr, cfg_obj_y, cfg_obj_y_wr, cfg_obj_color,
    cfg_obj_color_wr, cfg_txt_ctrl, cfg_txt_ctrl_wr, cfg_txt_pos, cfg_txt_pos_wr, cfg_txt_color,
    cfg_txt_color_wr, cfg_txt_chars, cfg_txt_chars_wr, cfg_obj_label, cfg_obj_label_wr, cfg_obj2_ctrl,
    cfg_obj2_ctrl_wr, cfg_obj2_x, cfg_obj2_x_wr, cfg_obj2_y, cfg_obj2_y_wr, cfg_obj2_color, cfg_obj2_color_wr,
    cfg_obj2_label, cfg_obj2_label_wr, sts_commit, sts_status, sts_frame_num);
endinterface
